"Yes."

pt:
//【景明】
<voice name='景明' class='景明' src='voice/md02/0130320a00'>
//「はい」
"Sim."

en:
//【童心】
<voice name='童心' class='童心' src='voice/md02/0130330a09'>
//「……なるほどのう」
"I see..."

pt:
//【童心】
<voice name='童心' class='童心' src='voice/md02/0130330a09'>
//「……なるほどのう」
"Entendo..."

en:
