"Não se atreva a seguir meu conselho agora, está me ouvindo! Senão viverei para me arrepender!"

en:
//【童心】
<voice name='童心' class='童心' src='voice/md02/0131260a09'>
//「はぁっはっはっはっはっはっはっはっ!!」
"HA HA HA HA HA HA HA!"

pt:
//【童心】
<voice name='童心' class='童心' src='voice/md02/0131260a09'>
//「はぁっはっはっはっはっはっはっはっ!!」
"HA HA HA HA HA HA HA!"

en:
//【景明】
<voice name='景明' class='景明' src='voice/md02/0131270a00'>
